settings.code:
{%- comment -%}
  ===== MENU COLLECTIONS (Desktop + Mobile, simple) =====
  Menu utilisé : sacs-par-collection
  - Barre horizontale simple
  - Défilement horizontal si trop de liens
  - Pas de "Voir tout"
  - Collection active en gras
{%- endcomment -%}

{%- assign menu_handle = 'sacs-par-collection' -%}
{%- assign nav = linklists[menu_handle] -%}

{%- if nav and nav.links.size > 0 -%}
  <style>
    .bti-collmenu { position: relative; margin: 8px 0 18px; }

    .bti-bar {
      display: flex; align-items: center; gap: 20px;
      overflow-x: auto; -webkit-overflow-scrolling: touch;
      padding: 10px 0; scrollbar-width: thin;
      border-bottom: 1px solid #eee;
    }
    .bti-bar::-webkit-scrollbar { height: 6px; }
    .bti-bar::-webkit-scrollbar-thumb { background: rgba(0,0,0,.15); border-radius: 4px; }

    .bti-link {
      text-decoration: none; white-space: nowrap;
      opacity: .8; transition: opacity .2s ease;
      font-size: 15px; letter-spacing: .02em;
    }
    .bti-link:hover { opacity: 1; }
    .bti-link.is-active {
      font-weight: 600;
      opacity: 1;
    }
  </style>

  <div class="bti-collmenu">
    <nav class="bti-bar" aria-label="Collections">
      {%- for l in nav.links -%}
        {%- assign active = false -%}
        {%- if collection and l.type == 'collection_link' and l.object and l.object.handle == collection.handle -%}
          {%- assign active = true -%}
        {%- endif -%}
        <a href="{{ l.url }}" class="bti-link {% if active %}is-active{% endif %}">{{ l.title }}</a>
      {%- endfor -%}
    </nav>
  </div>
{%- else -%}
  <p style="opacity:.7">⚠️ Le menu <code>{{ menu_handle }}</code> est introuvable.
  Crée-le dans <em>Navigation</em> et remplace le handle ci-dessus.</p>
{%- endif -%}
